package org.eclipse.rdf4j.sail.lmdb.evaluation;

import java.util.concurrent.atomic.LongAdder;

import org.eclipse.rdf4j.common.annotation.Experimental;
import org.eclipse.rdf4j.common.annotation.InternalUseOnly;

/**
 * A process-wide event count that every query thread updates for each row or term it handles. A single atomic counter
 * makes those threads take turns owning one cache line, which costs each of them far more than the count itself; this
 * counter keeps a cell per contending thread and sums the cells when it is read. A reading concurrent with updates may
 * miss the ones in flight, which is all a telemetry count ever promised.
 */
@Experimental
@InternalUseOnly
public final class NativeTelemetryCounter {

	private final LongAdder cells = new LongAdder();

	public void increment() {
		cells.increment();
	}

	public void add(long amount) {
		cells.add(amount);
	}

	public long get() {
		return cells.sum();
	}

	/** Replaces the count; only meaningful while nothing else is counting, as a test does before it measures. */
	public void set(long value) {
		cells.reset();
		if (value != 0L) {
			cells.add(value);
		}
	}
}
